#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Build the checks superset workflows from filters.json and the member workflow files.

A member is a former stand-alone workflow. Its file stays in .github/workflows with its jobs as the source of
truth and only `workflow_dispatch` (plus `workflow_call` when it had one) as trigger; its former push /
pull_request triggers live in filters.json. Each member job is copied byte for byte into one shard file
.github/workflows/checks-superset-NN.yml, with only these keys added or replaced:
  name         '<member workflow name> / <job name or id>'
  needs        gate + the member's own needs (job ids prefixed '<member>__')
  if           the gate decision for the member && the job's own condition
  permissions  the member's top-level permissions when the job has none
  env          the member's top-level env merged under the job env
  concurrency  the member's top-level concurrency (github.workflow -> member name; suffixed with the job id
               for multi-job members and with strategy.job-index for matrix jobs)
A shard's own triggers are the union of its members' triggers (positive patterns only, so a superset of
each member); the gate job (gate.py) then applies each member's exact filters.

Usage (needs PyYAML):
  generate.py init <workflow.yml>...   record the files' triggers in filters.json, assign shards, and switch
                                      the files to workflow_dispatch (former block kept as a comment)
  generate.py build                   write .github/workflows/checks-superset-NN.yml and verify each job
  generate.py check                   exit 1 when a shard file differs from what build would write
"""
import copy
import hashlib
import json
import os
import re
import sys

import yaml

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from gate import matched  # noqa: E402  (same filter semantics as the gate)

DEFAULT_BRANCH = "master"
ROOT = os.path.dirname(os.path.dirname(HERE))
WF = os.path.join(ROOT, ".github", "workflows")
FILTERS = os.path.join(HERE, "filters.json")
LIMIT_BYTES, LIMIT_JOBS = 360_000, 200
DEFAULT_TYPES = ["opened", "synchronize", "reopened"]
KEPT_TRIGGERS = ("push", "pull_request", "workflow_dispatch", "schedule")
TOP_ALLOWED = {"name", "on", "jobs", "concurrency", "permissions", "env"}
GATE_IF = "fromJSON(needs.gate.outputs.run || '{{}}')['{key}']"
Q = lambda s: json.dumps(s, ensure_ascii=False)
SELECT_INPUT = {"description": "Members to run: all, or member file names / keys separated by spaces or commas",
                "required": False, "default": "all"}
HEAD = """# SPDX-License-Identifier: Apache-2.0
# Checks superset @SHARD@: generated by .github/checks-superset/generate.py from filters.json and the member
# workflow files, which stay the source of truth for every member job below. Do not edit by hand: edit the
# member file, then run  python3 .github/checks-superset/generate.py build
name: 'Checks superset @SHARD@'

on:
@ON@

concurrency:
  group: ${{ github.workflow }}-${{ github.ref == 'refs/heads/master' && github.run_id || github.ref }}
  cancel-in-progress: ${{ github.ref != 'refs/heads/master' }}

jobs:
  gate:
    name: 'Superset gate'
    runs-on: ubuntu-24.04
    permissions:
      contents: read
    outputs:
      run: ${{ steps.gate.outputs.run }}
    steps:
      - name: 'Check out the gate files'
        uses: actions/checkout@v4
        with:
          sparse-checkout: .github/checks-superset
          fetch-depth: 1
          filter: blob:none
      - name: 'Decide member workflows from triggers, branches and changed paths (plain git)'
        id: gate
        run: python3 .github/checks-superset/gate.py @SHARD@

"""


def read(path):
    with open(path, encoding="utf-8", newline="") as f:
        return f.read()


def write(path, text):
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def load(text):
    doc = yaml.safe_load(text)
    if True in doc:
        doc["on"] = doc.pop(True)
    return doc


def triggers(doc):
    on = doc["on"]
    on = {on: None} if isinstance(on, str) else ({k: None for k in on} if isinstance(on, list) else dict(on))
    out = {k: dict(v or {}) for k, v in on.items() if k != "schedule"}
    for spec in out.values():
        for f in ("branches", "branches-ignore", "tags", "tags-ignore", "paths", "paths-ignore", "types"):
            if isinstance(spec.get(f), str):
                spec[f] = [spec[f]]
    if "schedule" in on:
        out["schedule"] = [c["cron"] for c in on["schedule"]]
    return out


def indent(line):
    return len(line) - len(line.lstrip(" "))


def top_blocks(text):
    """Top-level key -> its lines (comment / blank lines go with the block above)."""
    blocks, cur = {}, None
    for line in text.split("\n"):
        m = re.match(r"^([A-Za-z_][\w-]*)\s*:", line)
        if m:
            cur = m.group(1)
            blocks[cur] = []
        if cur is not None:
            blocks[cur].append(line)
    return blocks


def job_blocks(jobs_lines):
    jobs, cur = {}, None
    for line in jobs_lines[1:]:
        m = re.match(r"^  ([A-Za-z_][\w-]*)\s*:\s*(#.*)?$", line)
        if m:
            cur = m.group(1)
            jobs[cur] = [line]
        elif cur is not None:
            jobs[cur].append(line)
    for lines in jobs.values():
        while lines and not lines[-1].strip():
            lines.pop()
    return jobs


def child_indent(body):
    return next(indent(l) for l in body if l.strip() and not l.lstrip().startswith("#"))


def drop_keys(body, ci, keys):
    """Remove child keys (with their nested lines) from a job body; everything else stays byte for byte."""
    out, skipping = [], False
    for line in body:
        m = re.match(r"^ {%d}([A-Za-z_][\w-]*)\s*:" % ci, line)
        if m:
            skipping = m.group(1) in keys
        elif line.strip() and indent(line) <= ci:
            skipping = False
        if not skipping:
            out.append(line)
    return out


def member_ids(key, jobs):
    base = key if len(key) <= 70 else key[:60] + "-" + hashlib.sha1(key.encode()).hexdigest()[:8]
    return {j: f"{base}__{j}" for j in jobs}


def rewrite_needs(s, ids):
    return re.sub(r"\bneeds\.([A-Za-z_][\w-]*)", lambda m: "needs." + ids.get(m.group(1), m.group(1)), s)


def rewrite_obj(o, ids):
    if isinstance(o, str):
        return rewrite_needs(o, ids)
    if isinstance(o, list):
        return [rewrite_obj(x, ids) for x in o]
    if isinstance(o, dict):
        return {k: rewrite_obj(v, ids) for k, v in o.items()}
    return o


def combined_if(key, own, ids):
    gate = GATE_IF.format(key=key)
    if own is None:
        return "${{ " + gate + " }}"
    own = rewrite_needs(str(own).lower() if isinstance(own, bool) else str(own), ids).strip()
    m = re.fullmatch(r"\$\{\{(.*)\}\}", own, re.S)
    return "${{ " + gate + " && (" + (m.group(1).strip() if m else own) + ") }}"


def job_concurrency(member, doc, jid, job):
    c = doc["concurrency"]
    c = {"group": c} if isinstance(c, str) else dict(c)
    group = re.sub(r"\$\{\{\s*github\.workflow\s*\}\}", member["name"], str(c["group"]))
    group += f"-{jid}" if len(doc["jobs"]) > 1 else ""
    group += "-${{ strategy.job-index }}" if "matrix" in (job.get("strategy") or {}) else ""
    return {"group": group, **({"cancel-in-progress": c["cancel-in-progress"]} if "cancel-in-progress" in c else {})}


def expected_job(key, member, doc, jid, ids):
    old = rewrite_obj(copy.deepcopy(doc["jobs"][jid]), ids)
    own_needs = old.get("needs") or []
    own_needs = [own_needs] if isinstance(own_needs, str) else own_needs
    exp = {**old, "name": f"{member['name']} / {doc['jobs'][jid].get('name', jid)}",
           "needs": ["gate"] + [ids[n] for n in own_needs], "if": combined_if(key, doc["jobs"][jid].get("if"), ids)}
    if "permissions" not in old and "permissions" in doc:
        exp["permissions"] = doc["permissions"]
    if "env" in doc:
        exp["env"] = {**doc["env"], **(old.get("env") or {})}
    if "concurrency" not in old and "concurrency" in doc:
        exp["concurrency"] = job_concurrency(member, doc, jid, old)
    return exp


def trim(lines):
    lines = list(lines)
    while lines and (not lines[-1].strip() or lines[-1].lstrip().startswith("#")):
        lines.pop()
    return lines


def reindent(lines, shift):
    return [(" " * shift + l) if l.strip() else "" for l in lines]


def emit_kv(ci, k, v):
    if isinstance(v, dict):
        return [" " * ci + f"{k}:"] + [l for kk, vv in v.items() for l in emit_kv(ci + 2, kk, vv)]
    return [" " * ci + f"{k}: " + (Q(v) if isinstance(v, (str, list)) else json.dumps(v))]


def render_member(key, member):
    text = read(os.path.join(WF, member["file"]))
    doc, blocks = load(text), top_blocks(text)
    extra = set(k if isinstance(k, str) else "on" for k in doc) - TOP_ALLOWED
    if extra:
        sys.exit(f"{member['file']}: top-level keys {sorted(extra)} have no superset mapping")
    jobs = job_blocks(blocks["jobs"])
    if list(jobs) != list(doc["jobs"]):
        sys.exit(f"{member['file']}: job headers {list(jobs)} do not match parsed jobs {list(doc['jobs'])}")
    ids, out = member_ids(key, jobs), []
    for jid, lines in jobs.items():
        job, body = doc["jobs"][jid], lines[1:]
        ci = child_indent(body)
        exp = expected_job(key, member, doc, jid, ids)
        drop = {"name", "needs", "if"} | ({"env"} if "env" in doc else set())
        body = [rewrite_needs(l, ids) for l in drop_keys(body, ci, drop)]
        head = [" " * ci + "name: " + Q(exp["name"]), " " * ci + "needs: " + Q(exp["needs"]),
                " " * ci + "if: " + Q(exp["if"])]
        if "permissions" not in job and "permissions" in doc:
            head += reindent(trim(blocks["permissions"]), ci)
        if "env" in doc:
            head += emit_kv(ci, "env", exp["env"])
        if "concurrency" not in job and "concurrency" in doc:
            head += emit_kv(ci, "concurrency", exp["concurrency"])
        out += [f"  {ids[jid]}:"] + head + [l.rstrip("\r") for l in body] + [""]
    return out


def subsume(pats):
    """Drop a pattern that a plain 'dir/**' pattern of the same list already matches (no widening)."""
    dirs = [p[:-3] for p in pats if p.endswith("/**") and not re.search(r"[*?+\[\\!]", p[:-3])]
    if "**" in pats:
        return ["**"]
    return [p for p in pats if not any(p != d + "/**" and p.startswith(d + "/") for d in dirs)]


def union(specs, kind):
    """Trigger filter that fires whenever any member's filter fires (negated patterns dropped)."""
    out = {}
    refs = [("branches", "branches-ignore", "tags", "tags-ignore")]
    if kind == "push":
        refs.append(("tags", "tags-ignore", "branches", "branches-ignore"))
    for inc, exc, oth, oth_exc in refs:
        everything = any(exc in s or not any(k in s for k in (inc, oth, oth_exc)) for s in specs)
        pats = subsume(sorted({p for s in specs for p in s.get(inc, []) if not p.startswith("!")}))
        if everything or pats:
            out[inc] = ["**"] if everything else pats
    if out.get("branches") == ["**"] and (kind == "pull_request" or out.get("tags") == ["**"]):
        out = {}
    if all("paths" in s for s in specs):
        out["paths"] = subsume(sorted({p for s in specs for p in s["paths"] if not p.startswith("!")}))
    if any("types" in s for s in specs):
        out["types"] = sorted({t for s in specs for t in s.get("types", DEFAULT_TYPES)})
    return out


def dispatch_inputs(members):
    """select plus the union of the members' own workflow_dispatch inputs (same definitions)."""
    inputs = {"select": SELECT_INPUT}
    for m in members:
        own = triggers(load(read(os.path.join(WF, m["file"])))).get("workflow_dispatch", {}).get("inputs") or {}
        for name, spec in own.items():
            if inputs.setdefault(name, spec) != spec:
                sys.exit(f"{m['file']}: dispatch input '{name}' conflicts with another member of the shard")
    return inputs


def render_shard(shard, keys, filters):
    members = [filters["members"][k] for k in keys]
    on = []
    for kind in ("push", "pull_request"):
        specs = [m[kind] for m in members if kind in m]
        if specs:
            u = union(specs, kind)
            on += [f"  {kind}:"] + ([l for k, v in u.items() for l in emit_kv(4, k, v)] if u else [])
    if any("workflow_dispatch" in m for m in members):
        on += emit_kv(2, "workflow_dispatch", {"inputs": dispatch_inputs(members)})
    head = HEAD.replace("@SHARD@", shard).replace("@ON@", "\n".join(on))
    body = [l for k in keys for l in render_member(k, filters["members"][k])]
    return head + "\n".join(body).rstrip("\n") + "\n"


def verify(shard, keys, filters, text):
    doc, problems = load(text), []
    for key in keys:
        member = filters["members"][key]
        mdoc = load(read(os.path.join(WF, member["file"])))
        ids = member_ids(key, mdoc["jobs"])
        for jid in mdoc["jobs"]:
            if doc["jobs"].get(ids[jid]) != expected_job(key, member, mdoc, jid, ids):
                problems.append(f"shard {shard}: {member['file']} job {jid} differs from its member job")
    legs = len(doc["jobs"])
    if len(text.encode()) > 450_000 or legs > LIMIT_JOBS + 1:
        problems.append(f"shard {shard}: {len(text.encode())} bytes, {legs} jobs over the limits")
    return problems


def shard_file(shard):
    return os.path.join(WF, f"checks-superset-{shard}.yml")


def mapping(filters):
    """MAPPING.tsv: former workflow -> superset file and job ids, with the triggers it keeps."""
    rows = ["former_file\tformer_name\tsuperset_file\tjob_ids\tpush\tpull_request\tworkflow_dispatch"]
    for s, keys in filters["shards"].items():
        for k in keys:
            m = filters["members"][k]
            ids = member_ids(k, load(read(os.path.join(WF, m["file"])))["jobs"]).values()
            cell = lambda t: json.dumps({x: y for x, y in m[t].items()}, ensure_ascii=False) if t in m else "-"
            rows.append("\t".join([m["file"], m["name"], os.path.basename(shard_file(s)), " ".join(ids),
                                   cell("push"), cell("pull_request"), cell("workflow_dispatch")]))
    return "\n".join(rows) + "\n"


def build(check_only=False):
    filters, problems = json.loads(read(FILTERS)), []
    outputs = {os.path.join(HERE, "MAPPING.tsv"): mapping(filters)}
    for shard, keys in filters["shards"].items():
        text = render_shard(shard, keys, filters)
        problems += verify(shard, keys, filters, text)
        outputs[shard_file(shard)] = text
        print(f"shard={shard} members={len(keys)} bytes={len(text.encode())} jobs={len(load(text)['jobs'])}")
    for path, text in outputs.items():
        if check_only:
            problems += [] if os.path.exists(path) and read(path) == text else [f"{path}: stale, run build"]
        else:
            write(path, text)
    print("\n".join(problems) or "verify: every member job matches its source job")
    return 1 if problems else 0


def artifact_names(doc):
    return {str((s.get("with") or {}).get("name", "artifact")) for j in doc["jobs"].values()
            for s in (j.get("steps") or []) if "upload-artifact" in str(s.get("uses", ""))}


def legs(doc):
    def one(job):
        m = (job.get("strategy") or {}).get("matrix")
        if not isinstance(m, dict):
            return 1
        axes = [len(v) for k, v in m.items() if k not in ("include", "exclude") and isinstance(v, list)]
        n = 1
        for a in axes:
            n *= a
        return max(n, len(m.get("include") or []) if not axes else n)
    return sum(one(j) for j in doc["jobs"].values())


def broad(pattern):
    """A path pattern that covers a whole top-level area: '<at most two dirs>/**...' (src/java.base/**)."""
    m = re.match(r"^((?:[^/*?+\[!]+/){0,2})\*\*", pattern)
    return bool(m) and not pattern.startswith(".github/")


def area(trig):
    """Sort key that keeps members of the same source area together (first three fixed path segments)."""
    pats = [p for p in (trig.get("pull_request") or trig.get("push") or {}).get("paths", []) if not p.startswith(".")]
    heads = ["/".join(re.split(r"[*?+\[]", p)[0].split("/")[:3]) for p in pats]
    return max(sorted(set(heads)), key=heads.count) if heads else ""


def profile(trig):
    """Shard group: members that start runs on the same kinds of events and areas share shards, so a shard's
    union triggers stay as narrow as its members' and one change starts as few shards as possible."""
    push, pr = trig.get("push"), trig.get("pull_request")
    if push is not None and "branches" not in push:
        return "push-paths" if "paths" in push or "paths-ignore" in push else "push-all"
    pr_all = pr is not None and "paths" not in pr and "paths-ignore" not in pr
    if push is not None and matched(push["branches"], DEFAULT_BRANCH) and not pr_all:
        return "default-push-paths" if "paths" in push or "paths-ignore" in push else "every-pr-or-default-push"
    if pr_all:
        return "every-pr-or-default-push"
    return "broad" if any(broad(p) for p in (pr or {}).get("paths", [])) else "narrow"


def switch_triggers(path, member, shard):
    """Keep only workflow_dispatch (and workflow_call) blocks; the former on: block stays as a comment."""
    text = read(path)
    lines = text.split("\n")
    start = next(i for i, l in enumerate(lines) if re.match(r"^on\s*:", l))
    end = next((i for i in range(start + 1, len(lines)) if re.match(r"^[A-Za-z_]", lines[i])), len(lines))
    while end > start + 1 and (not lines[end - 1].strip() or lines[end - 1].startswith("#")):
        end -= 1
    old, keep, cur = lines[start:end], [], None
    for l in old[1:]:
        m = re.match(r"^  ([A-Za-z_][\w-]*)\s*:", l)
        cur = m.group(1) if m else (cur if (not l.strip() or indent(l) > 2) else None)
        if cur in ("workflow_dispatch", "workflow_call"):
            keep.append(l)
    if not any(re.match(r"^  workflow_dispatch\s*:", l) for l in keep):
        keep.insert(0, "  workflow_dispatch:")
    base = next(iter(member_ids(member["key"], ["x"]).values()))[:-1]
    note = [f"# Former triggers (below, as of the move) now start job(s) '{base}*' in",
            f"# .github/workflows/checks-superset-{shard}.yml, gated by the same filters (.github/checks-superset/filters.json).",
            "# This file keeps the jobs as the source of truth and runs by hand; after editing them run",
            "#   python3 .github/checks-superset/generate.py build"]
    new = note + ["#   " + l if l.strip() else "#" for l in old] + ["on:"] + keep
    write(path, "\n".join(lines[:start] + new + lines[end:]))


def init(files):
    filters = json.loads(read(FILTERS)) if os.path.exists(FILTERS) else {"shards": {}, "members": {}}
    sizes = {s: [0, 0, set(), filters["members"][ks[0]]["profile"]] for s, ks in filters["shards"].items() if ks}
    for s, ks in filters["shards"].items():
        for k in ks:
            d = load(read(os.path.join(WF, filters["members"][k]["file"])))
            sizes[s][0] += len(read(os.path.join(WF, filters["members"][k]["file"])).encode())
            sizes[s][1] += legs(d); sizes[s][2] |= artifact_names(d)
    trig_of = {f: triggers(load(read(os.path.join(WF, f)))) for f in files}
    for f in sorted(files, key=lambda f: (profile(trig_of[f]), area(trig_of[f]), f)):
        text = read(os.path.join(WF, f)); doc = load(text); trig = triggers(doc)
        key, prof = os.path.splitext(f)[0], profile(trig)
        size, n, arts = len(text.encode()), legs(doc), artifact_names(doc)
        room = [s for s, v in sizes.items() if v[0] + size <= LIMIT_BYTES and v[1] + n <= LIMIT_JOBS]
        fits = [s for s in room if not sizes[s][2] & arts]
        shard = next((s for s in fits if sizes[s][3] == prof), None)
        if shard is None and any(sizes[s][3] == prof for s in room):  # room, but an artifact name collides
            wider = {"narrow": ["broad", "every-pr-or-default-push"], "broad": ["every-pr-or-default-push"]}
            shard = next((s for p in wider.get(prof, []) for s in fits if sizes[s][3] == p), None)
        if shard is None:
            shard = f"{len(sizes) + 1:02d}"
            sizes[shard] = [0, 0, set(), prof]
            filters["shards"][shard] = []
        sizes[shard][0] += size; sizes[shard][1] += n; sizes[shard][2] |= arts
        member = {"file": f, "name": str(doc.get("name", f)), "profile": prof, "shard": shard, "key": key}
        member.update({k: v for k, v in trig.items() if k in KEPT_TRIGGERS})
        if "workflow_dispatch" in member:
            member["workflow_dispatch"] = {"inputs": sorted((member["workflow_dispatch"].get("inputs") or {}))}
        filters["members"][key] = member
        filters["shards"][shard].append(key)
        switch_triggers(os.path.join(WF, f), member, shard)
    write(FILTERS, json.dumps(filters, indent=1, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "build"
    if cmd == "init":
        init([os.path.basename(f) for f in sys.argv[2:]])
    else:
        sys.exit(build(check_only=cmd == "check"))
